""" #> IMPORTS =======================
================================== """

#> imports
import os
import sys
import glob
import numpy as np
import matplotlib.pyplot as plt

#> adding opus path
sys.path.insert(0, '../opus')

#> modules
import plot
import generate
import modules.parse as parse

#> declarations
outFolder = '../../arrival_order/data/increment' # increment data


""" #> PARAMS ========================
================================== """

#> profile subscripts
PROFILES = {'nfw':  r'\bullet',
            'hern': r'\star',
            'ex':   r'\gamma'}

#> param symbols
SYMBOLS = {'axisrat': r'q_{%s}',
           'theta':   r'\theta_{%s}',
           'x0':      r'x_{0,%s}',
           'y0':      r'y_{0,%s}',
           'norm':    r'a_{%s}'}

#> multipole symbols
MULT = {'norm':  r'a_{%s}',
        'theta': r'\theta_{m_%s}'}

#> labels that don't follow the pattern
SPECIAL = {'both_axisrat': r'q_{\bullet} = q_{\star}',
           'ex_norm':      r'\gamma'}

#> returns x label of a param folder
def labels(folder):
    
    #> special cases
    if folder in SPECIAL: return f'${SPECIAL[folder]}$'
    
    #> symbol + profile subscript
    prof, param = folder.split('_')[0], folder.split('_')[-1]
    symbols = MULT if prof in ['mult'] else SYMBOLS
    return f'${symbols[param] % subscript(folder)}$'

#> profile subscript of a param folder (e.g., nfw_theta --> \bullet, mult_m3_norm --> 3)
def subscript(folder):
    prof, *rest = folder.split('_')
    if prof in ['mult']: return rest[0][1:]
    return PROFILES[prof]


""" #> LOADING =======================
================================== """

#> main run folder
def run_dir(outFolder):
    return generate.dataDir + outFolder

#> loads main run folder files
def load_run(outFolder):
    return parse.load(run_dir(outFolder))

#> loads every bin of every incremented param
def load_param(outFolder, folder):
    return parse.load_folders(os.path.join(run_dir(outFolder), folder))

#> loads the whole increment.py run
def read(**kwargs):

    #> kwargs
    outFolder = kwargs.get('outFolder', globals()['outFolder'])  # run folder (inside generate.dataDir)

    #> run info + redraws
    run = load_run(outFolder)

    #> every param: {folder: [bin 0, bin 1, ...]}
    data = {folder: load_param(outFolder, folder) for folder in run['info']['points']}

    return run, data


""" #> CONFIGURATIONS ================
================================== """

#> every bin folder of one incremented param (sorted = save order = bin order, as in parse.load_folders)
def bin_dirs(outFolder, folder):
    path = os.path.join(run_dir(outFolder), folder)
    return sorted(d for d in glob.glob(os.path.join(path, '*')) if os.path.isdir(d))


#> config file of one bin folder: <bin>/<bin>_config.npy (same naming as generate.save())
def config_file(bdir):
    name = os.path.basename(os.path.normpath(bdir))
    return os.path.join(bdir, f'{name}_config.npy')


#> calculates + writes the quad configurations of one bin folder (same as gen(config=True))
def write_config(bdir, method):
    
    #> images + number of images
    data = parse.load(bdir, keys=['images', 'nims'])
    
    #> configurations (EC, F, CM, Cm, overlaps, A = ambiguous, '' = not a quad)
    cfg = generate.quad_configs(data['images'], data['nims'] == 5, method)
    
    #> saving
    np.save(config_file(bdir), cfg)
    print(f'> Saved configs to {config_file(bdir)}')
    
    return

#> writes the quad configurations of every bin of every incremented param
def configs(**kwargs):
    
    #> kwargs
    outFolder = kwargs.get('outFolder', globals()['outFolder'])  # run folder (inside generate.dataDir)
    overwrite = kwargs.get('overwrite', False)                   # recalculates bins that already have a config file
    
    #> run info + image ordering of the run
    run    = load_run(outFolder)
    method = run['info']['kwargs'].get('method', 'deflect') # gen() default
    
    #> iterating through each param + bin
    for folder in run['info']['points']:
        for bdir in bin_dirs(outFolder, folder):
            
            #> skipping bins that already have configs
            if os.path.isfile(config_file(bdir)) and not overwrite: continue
            write_config(bdir, method)
    
    return


""" #> ANALYZE FNS ===================
================================== """

#> rescales bin values to [0, 1] (params have different ranges/units)
def rescale(x, xmin=None, xmax=None):
    
    #> declarations
    x = np.array(x)
    
    #> getting range
    if xmin is None: xmin = x.min()
    if xmax is None: xmax = x.max()
    return (x - x.min()) / (x.max() - x.min())

#> number of quads whose morph order matches the fermat order, per bin
def count_match(b_data):
    return [int(np.nansum(data['order_match'])) for data in b_data] # nan (non-quads) skipped

#> number of quads per bin
def count_quads(b_data):
    return [int(np.sum(~np.isnan(data['order_match']))) for data in b_data]

#> number of quads of each configuration, per bin
def config_count(b_data):
    
    #> iterating through each bin
    counts = []
    for data in b_data:
        
        #> quads only
        cfg = data['config'][data['config'] != '']
        
        #> unique configs + number of each
        names, n = np.unique(cfg, return_counts=True)
        counts.append({str(k): int(v) for k, v in zip(names, n)})
    
    return counts

#> order_match vs. inc param value
def order_match(run, folder, b_data):
    
    #> setting style
    plot.setStyle()
    
    #> initializing plot
    fig, ax = plt.subplots(1,1,figsize=(6,6))
    plot.styleAx(ax, xlabel=labels(folder), ylabel='% Order Mismatch')
    
    #> bin values + match counts
    x = run['info']['points'][folder]
    y = lambda d: np.array(count_match(d)) / np.array(count_quads(d)) # fraction of quads
    
    #> plottings
    ax.axhline(0.0, c='k', ls=':')
    ax.plot(x, (1-y(b_data))*100, marker='o')
    
    #> plotting configurations (% of quads in each config)
    counts = config_count(b_data)                          # {config: number} per bin
    nquad  = np.array(count_quads(b_data))                 # quads per bin
    names  = sorted(set().union(*counts))                  # every config found in any bin
    for name in names:
        n = np.array([c.get(name, 0) for c in counts])     # 0 if not in a bin
        ax.plot(x, n / nquad * 100, marker='.', ls='--', label=name)
    ax.legend(fontsize=12)
    
    #> plotting, saving, etc.
    plot.finish(fig, outFile=f'{folder}_mismatch', loc='../arrival_order/figures/mismatch/')
    
    return

#> order_match vs. inc param value, every param overplotted on one axis
def order_match_all(run, data):
    
    #> setting style
    plot.setStyle()
    
    #> initializing plot
    fig, ax = plt.subplots(1,1,figsize=(7,6))
    
    #> labels
    plot.styleAx(ax, xlabel='(p - min) / (max - min)', ylabel='% Order Mismatch')
    
    #> iterating through each param
    ax.axhline(0, c='k', ls=':')
    for i, (folder, b_data) in enumerate(data.items()):
        
        #> rescaled bin values + match fraction
        x = rescale(run['info']['points'][folder])
        y = (1 - np.array(count_match(b_data)) / np.array(count_quads(b_data))) * 100
        
        #> plotting
        ax.plot(x, y, marker='o', ms=4, c=plt.cm.tab20(i), label=labels(folder)) # tab20: no repeated colors
    
    #> limits, legend
    ax.set_ylim(-1, 15)
    plot.ticks(ax, xnum=6, ynum=6, method='max')
    ax.legend(ncols=3, fontsize=12)
    
    #> plotting, saving, etc.
    plot.finish(fig, outFile='increment_mismatch', loc='../arrival_order/figures/mismatch/')
    
    return

""" #> MAIN ==========================
================================== """

#> main function
if __name__ == '__main__':

    #> name
    print('> '+os.path.basename(__file__))

    #> loading
    run, data = read(outFolder=outFolder)
    
    print(run.keys())

    #> example: fraction of quads whose morph order matches the fermat order, per bin
    for folder, b_data in data.items():
        
        order_match(run, folder, b_data)

    #> every param together
    order_match_all(run, data)

    # end
